    `,tech:["Next.js / React","Multi-Step Eligibility Form Engine","Dynamic Lead Routing API","Mobile-First Responsive Layout","Local SEO Optimization","Fast Caching & Performance Tuning"],images:["https://i.ibb.co/LzmZz63j/Untitled-design.jpg","https://i.ibb.co/Yk2xZQk/shalimar-smart-city-banner.png"],reverse:!0},{slug:"pos-inventory-analytics-dashboard",title:"Multi-Store POS & Inventory Dashboard",banner:"https://i.ibb.co/HTDf1qY8/Screenshot-2026-08-20-at-4-29-19-PM.png",card_image:"https://i.ibb.co/HTDf1qY8/Screenshot-2026-08-20-at-4-29-19-PM.png",category:"Admin Dashboards",client:"Retail & E-Commerce Client",location:"Lahore, Pakistan",published:"2026-02-10",description:`
